from fastapi import FastAPI, Depends, HTTPException, Header

app = FastAPI()

def get_token_header(x_token: str = Header()):
    if x_token != "fake-super-secret-token":
        raise HTTPException(status_code=400, detail="X-Token header invalid")

def get_query_token(token: str):
    if token != "jessica":
        raise HTTPException(status_code=400, detail="No Jessica token provided")

@app.get("/items/", dependencies=[Depends(get_token_header), Depends(get_query_token)])
def read_items():
    return [{"item": "Foo"}, {"item": "Bar"}]
EOF

cat > main.py << 'EOF'
from fastapi import FastAPI, BackgroundTasks

app = FastAPI()

def write_notification(email: str, message: str):
    with open("/tmp/notifications.log", "a") as log:
        log.write(f"{email}: {message}\n")

@app.post("/send-notification/{email}")
def send_notification(email: str, message: str, background_tasks: BackgroundTasks):
    background_tasks.add_task(write_notification, email, message)
    return {"message": "Notification sent in the background"}
EOF
